 current=page.locator('.pilot-motif .current');assert current.inner_text().splitlines()[0]=='E';cell=page.locator('[data-pilot-string="0"][data-pilot-fret="0"]');cell.dispatch_event('pointerdown',{'button':0,'clientX':100,'clientY':220});page.wait_for_function('window.__audio.length===1');first_index=snap(page)['session']['motifIndex'];assert first_index==0
 # The repeated E is the second note of this real incipit. No 500ms wait.
