 # A non-uniform model verifies that the real excerpt's rhythm is retained.
 page.evaluate('''async k=>{const {pilotPlan,practiceActivities,questionsFor}=await import('./pilot.js'),d=JSON.parse(localStorage.getItem(k)),v=Object.values(d.profiles)[0],m=practiceActivities(pilotPlan(v.profile)).find(m=>m.id==='degree-4-find');v.seenInstructions=['motif','melody-degree-4'];v.session={id:'rhythm',activity:m.id,stage:'motif',queue:questionsFor(m),events:[],index:20,motifIndex:0,motifErrors:0,startedAt:1};localStorage.setItem(k,JSON.stringify(d))}''',KEY);page.reload();page.locator('[data-pilot-action="resume"]').click();dismiss_help(page);page.locator('[data-pilot-action="mute"]').click();page.locator('[data-pilot-action="replay"]').click();page.wait_for_function('window.__audio.length===4');notes=page.evaluate('window.__audio');assert all(abs(z['when']-a['when']-expected)<.001 for a,z,expected in zip(notes,notes[1:],[.84,.63,.21]))
